import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p29_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor softplus_forward(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softplus_forward", &softplus_forward, "Softplus forward (CUDA float32 contiguous)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void softplus_kernel_f32(const float* __restrict__ in, float* __restrict__ out, int64_t n) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    // Process 4 elements per thread via float4 vectorization
    int64_t n4 = n / 4;
    const float4* in4 = reinterpret_cast<const float4*>(in);
    float4* out4 = reinterpret_cast<float4*>(out);
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = __ldg(in4 + i);
        float4 r;
        r.x = v.x > 20.0f ? v.x : __logf(1.0f + __expf(v.x));
        r.y = v.y > 20.0f ? v.y : __logf(1.0f + __expf(v.y));
        r.z = v.z > 20.0f ? v.z : __logf(1.0f + __expf(v.z));
        r.w = v.w > 20.0f ? v.w : __logf(1.0f + __expf(v.w));
        out4[i] = r;
    }
    // Handle tail
    int64_t tail_start = n4 * 4;
    for (int64_t i = tail_start + idx; i < n; i += stride) {
        float v = __ldg(in + i);
        out[i] = v > 20.0f ? v : __logf(1.0f + __expf(v));
    }
}

torch::Tensor softplus_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "softplus_forward: input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "softplus_forward: input must be float32");
    TORCH_CHECK(x.is_contiguous(), "softplus_forward: input must be contiguous");
    auto out = torch::empty_like(x);
    int64_t n = x.numel();
    if (n == 0) return out;
    const int threads = 256;
    int64_t n4 = n / 4;
    int64_t work = (n4 > 0) ? n4 : n;
    int blocks = (int)std::min((work + threads - 1) / threads, (int64_t)65535);
    softplus_kernel_f32<<<blocks, threads>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), n);
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a Softplus activation.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if x.is_cuda and x.dtype == torch.float32 and x.is_contiguous():
                    return _stark_get_extension().softplus_forward(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return torch.nn.functional.softplus(x)
        # <<<END_IMPROVE>>>

