    // Branch-minimized stable Softplus: max(x,0) + log1p(exp(-|x|))
    // Avoids overflow for large positive x, underflow for large negative x.
    float ax = fabsf(x);
    float pos = (x > 0.0f) ? x : 0.0f;
    return pos + __logf(1.0f + __expf(-ax));
}

