        float4 v0 = __ldg(in + i);
        float4 v1 = __ldg(in + i + 1);

        float4 r0, r1;
        r0.x = softplus_stable(v0.x);
        r0.y = softplus_stable(v0.y);
        r0.z = softplus_stable(v0.z);
        r0.w = softplus_stable(v0.w);

        r1.x = softplus_stable(v1.x);
        r1.y = softplus_stable(v1.y);
        r1.z = softplus_stable(v1.z);
        r1.w = softplus_stable(v1.w);

